window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-10001\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεκπαίω</h1><div class=\"entry-meta\"><span>DGP · ordem 1483 na letra δ · nº geral 10001</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">abrir uma passagem a golpes através de, gen. ou ac. ou διά e gen.</p></section></article>\n<article id=\"entry-dgp-10002\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεκπεράω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1484 na letra δ · nº geral 10002</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. διεξεπέρησα) passar além; atravessar.</p></section></article>\n<article id=\"entry-dgp-10003\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεκπίπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 1485 na letra δ · nº geral 10003</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor.2 διεξέπεσον) 1 cair através; escapar através, gen. ou ac. ou διά e gen. 2 chegar em fuga a, εἰς e ac.</p></section></article>\n<article id=\"entry-dgp-10004\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεκπλέω</h1><div class=\"entry-meta\"><span>DGP · ordem 1486 na letra δ · nº geral 10004</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">atravessar navegando; abrir passagem com a frota, ac. ou gen.</p></section></article>\n<article id=\"entry-dgp-10005\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διέκπλοος, όου,</h1><div class=\"entry-meta\"><span>DGP · ordem 1487 na letra δ · nº geral 10005</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">contr. át. διέκπλους, ου (ὁ) 1 travessia marítima 2 travessia das linhas inimigas com uma frota. 〈διεκπλέω〉</p></section></article>\n<article id=\"entry-dgp-10006\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεκπλώω</h1><div class=\"entry-meta\"><span>DGP · ordem 1488 na letra δ · nº geral 10006</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = διεκπλέω.</p></section></article>\n<article id=\"entry-dgp-10007\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεκπνοή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1489 na letra δ · nº geral 10007</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 exalação 2 abertura para respiração. 〈διά, ἐκπνέω〉</p></section></article>\n<article id=\"entry-dgp-10008\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διέκριθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1490 na letra δ · nº geral 10008</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. aor. pas. eól. de διακρίνω.</p></section></article>\n<article id=\"entry-dgp-10009\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διέκροος, όου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1491 na letra δ · nº geral 10009</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">conduto de escoamento. 〈διά, ἐκρέω〉</p></section></article>\n<article id=\"entry-dgp-10010\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεκφεύγω</h1><div class=\"entry-meta\"><span>DGP · ordem 1492 na letra δ · nº geral 10010</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor.2 part. διεκφυγόντες) evitar; escapar de, ac.</p></section></article>\n<article id=\"entry-dgp-10011\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διέλασις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1493 na letra δ · nº geral 10011</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de impelir através; penetração 2 cargo ou exercício de cavalaria. 〈διελαύνω〉</p></section></article>\n<article id=\"entry-dgp-10012\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διελαύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1494 na letra δ · nº geral 10012</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. διήλασα, perf. διελήλακα) 1 impelir os cavalos, ac., através, gen. 2 cavalgar através; avançar através; penetar através, gen. ou ac. ou διά e gen. 3 avançar; aparecer 4 perf. ter chegado ♦ méd. 5 atravessar; percorrer. 〈διά, ἐλαύνω〉</p></section></article>\n<article id=\"entry-dgp-10013\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διελεγκτέον</h1><div class=\"entry-meta\"><span>DGP · ordem 1495 na letra δ · nº geral 10013</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de διελέγχω.</p></section></article>\n<article id=\"entry-dgp-10014\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διελέγχω</h1><div class=\"entry-meta\"><span>DGP · ordem 1496 na letra δ · nº geral 10014</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) 1 refutar completamente 2 convencer; demonstrar; provar 3 investigar ♦ méd. 4 discutir.</p></section></article>\n<article id=\"entry-dgp-10015\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διελεῖν</h1><div class=\"entry-meta\"><span>DGP · ordem 1497 na letra δ · nº geral 10015</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 de διαιρέω.</p></section></article>\n<article id=\"entry-dgp-10016\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διελεύσομαι, διελήλυθα</h1><div class=\"entry-meta\"><span>DGP · ordem 1498 na letra δ · nº geral 10016</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. e perf. de διέρχομαι.</p></section></article>\n<article id=\"entry-dgp-10017\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διελέχθην</h1><div class=\"entry-meta\"><span>DGP · ordem 1499 na letra δ · nº geral 10017</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. ind. pas. de διαλέγω.</p></section></article>\n<article id=\"entry-dgp-10018\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διελίττω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1500 na letra δ · nº geral 10018</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -ίσσω (só pres.) 1 desenrolar; desdobrar; desenvolver; expor ♦ méd. 2 passar rolando sobre 3 virar.</p></section></article>\n<article id=\"entry-dgp-10019\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διέλκω</h1><div class=\"entry-meta\"><span>DGP · ordem 1501 na letra δ · nº geral 10019</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. διείλκυσα) 1 puxar através; fazer passar através 2 puxar em sentido contrário; afastar; abrir: δ. τοὺς ὀφθαλμούς plat. abrir os olhos 3 passar a vida ♦ méd. pas. 4 adiar; diferir ♦ pas. 5 (tempo) escoar-se. 〈διά, ἕλκω〉</p></section></article>\n<article id=\"entry-dgp-10020\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διελών, οῦσα, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1502 na letra δ · nº geral 10020</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor.2 de διαιρέω.</p></section></article>\n<article id=\"entry-dgp-10021\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίεμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1503 na letra δ · nº geral 10021</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. 1a sing. e 3a pl. δίενται) 1 fugir através, gen. 2 ter medo de; hesitar em, inf.</p></section></article>\n<article id=\"entry-dgp-10022\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διέμενος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1504 na letra δ · nº geral 10022</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor.2 de διΐημι.</p></section></article>\n<article id=\"entry-dgp-10023\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεμπολάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1505 na letra δ · nº geral 10023</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">vender; traficar; fazer comércio de, ac.</p></section></article>\n<article id=\"entry-dgp-10024\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεμφαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1506 na letra δ · nº geral 10024</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(part. pres.) mostrar; manifestar claramente.</p></section></article>\n<article id=\"entry-dgp-10025\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διενεγκεῖν</h1><div class=\"entry-meta\"><span>DGP · ordem 1507 na letra δ · nº geral 10025</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 de διαφέρω.</p></section></article>\n<article id=\"entry-dgp-10026\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διενειλέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1508 na letra δ · nº geral 10026</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(part. perf. pas. διενειλημένος) enrolar; embrulhar. 〈διά, ἐνειλέω〉</p></section></article>\n<article id=\"entry-dgp-10027\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διενεκτέον</h1><div class=\"entry-meta\"><span>DGP · ordem 1509 na letra δ · nº geral 10027</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de διαφέρω.</p></section></article>\n<article id=\"entry-dgp-10028\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διενεχθείς</h1><div class=\"entry-meta\"><span>DGP · ordem 1510 na letra δ · nº geral 10028</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor. pas. de διαφέρω.</p></section></article>\n<article id=\"entry-dgp-10029\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διενήνοχα</h1><div class=\"entry-meta\"><span>DGP · ordem 1511 na letra δ · nº geral 10029</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perf. de διαφέρω.</p></section></article>\n<article id=\"entry-dgp-10030\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διενθυμέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1512 na letra δ · nº geral 10030</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. = ἐνθυμέομαι.</p></section></article>\n<article id=\"entry-dgp-10031\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διενιαυτίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1513 na letra δ · nº geral 10031</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">viver um ano inteiro ou até o fim do ano. 〈διά, ἐνιαυτός〉</p></section></article>\n<article id=\"entry-dgp-10032\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίενται</h1><div class=\"entry-meta\"><span>DGP · ordem 1514 na letra δ · nº geral 10032</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. δίεμαι.</p></section></article>\n<article id=\"entry-dgp-10033\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διέξ</h1><div class=\"entry-meta\"><span>DGP · ordem 1515 na letra δ · nº geral 10033</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. διέκ.</p></section></article>\n<article id=\"entry-dgp-10034\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεξάγω</h1><div class=\"entry-meta\"><span>DGP · ordem 1516 na letra δ · nº geral 10034</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor.2 διεξήγαγον etc.) 1 fazer passar através de, conduzir por, διά e gen. 2 levar a cabo; conduzir até o fim; levar a termo; completar 3 dirigir; administrar 4 resolver.</p></section></article>\n<article id=\"entry-dgp-10035\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεξαγωγή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1517 na letra δ · nº geral 10035</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de levar a termo 2 conduta de vida 3 regulamento (de disputa) 4 administração; direção; governo. 〈διεξάγω〉</p></section></article>\n<article id=\"entry-dgp-10036\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεξαΐσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1518 na letra δ · nº geral 10036</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -ᾴττω e -άττω (aor. 3ª sing. διεξάϊξε) escapar com impetuosidade; arremessar-se.</p></section></article>\n<article id=\"entry-dgp-10037\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διέξειμι</h1><div class=\"entry-meta\"><span>DGP · ordem 1519 na letra δ · nº geral 10037</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(pres. 3a sing. διέξεισι, impf. διεξῄειν) 1 atravessar; percorrer, ac. ou διά e gen. 2 escapar 3 expor; contar.</p></section></article>\n<article id=\"entry-dgp-10038\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεξέλασις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1520 na letra δ · nº geral 10038</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">διέλασις.</p></section></article>\n<article id=\"entry-dgp-10039\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεξελαύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1521 na letra δ · nº geral 10039</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διεξελῶ, aor. διεξήλασα) 1 cavalgar 2 atravessar a cavalo, ac. ou gen. 3 avançar.</p></section></article>\n<article id=\"entry-dgp-10040\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεξελέγχω</h1><div class=\"entry-meta\"><span>DGP · ordem 1522 na letra δ · nº geral 10040</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">refutar totalmente.</p></section></article>\n<article id=\"entry-dgp-10041\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεξελεύσομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1523 na letra δ · nº geral 10041</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de διεξέρχομαι.</p></section></article>\n<article id=\"entry-dgp-10042\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεξελίσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 1524 na letra δ · nº geral 10042</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">desenvolver.</p></section></article>\n<article id=\"entry-dgp-10043\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεξερέομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1525 na letra δ · nº geral 10043</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) interrogar.</p></section></article>\n<article id=\"entry-dgp-10044\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεξέρχομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1526 na letra δ · nº geral 10044</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διεξελεύσομαι etc.) 1 atravessar, ac. ou διά e gen. 2 passar sucessivamente 3 expor; narrar; referir 4 (fato) desenrolar-se 5 (tempo) escoar-se.</p></section></article>\n<article id=\"entry-dgp-10045\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεξηγέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1527 na letra δ · nº geral 10045</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(inf. aor. διεξήσασθαι) expor; contar.</p></section></article>\n<article id=\"entry-dgp-10046\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεξήεϊε</h1><div class=\"entry-meta\"><span>DGP · ordem 1528 na letra δ · nº geral 10046</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª impf. jôn. de διέξειμι.</p></section></article>\n<article id=\"entry-dgp-10047\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεξιείς</h1><div class=\"entry-meta\"><span>DGP · ordem 1529 na letra δ · nº geral 10047</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. pres. ind. de διεξίημι.</p></section></article>\n<article id=\"entry-dgp-10048\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεξιέναι</h1><div class=\"entry-meta\"><span>DGP · ordem 1530 na letra δ · nº geral 10048</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. pres. de διέξειμι.</p></section></article>\n<article id=\"entry-dgp-10049\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεξίημι</h1><div class=\"entry-meta\"><span>DGP · ordem 1531 na letra δ · nº geral 10049</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. 3ª pl. διεξῆκαν) 1 deixar passar alguém, ac., através de, διά e gen. 2 (rio) lançar-se a, εἰς e ac.</p></section></article>\n<article id=\"entry-dgp-10050\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεξίμεναι</h1><div class=\"entry-meta\"><span>DGP · ordem 1532 na letra δ · nº geral 10050</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. pres. ép. de διέξειμι.</p></section></article>\n<article id=\"entry-dgp-10051\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεξιών, οῦσα, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1533 na letra δ · nº geral 10051</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. pres. de διέξειμι.</p></section></article>\n<article id=\"entry-dgp-10052\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεξοδικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1534 na letra δ · nº geral 10052</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que serve de saída 2 desenvolvido; extenso ♦ τὸ διεξοδικόν artt. 3 Anat. órgão de evacuação dos excrementos. 〈διέξοδος〉</p></section></article>\n<article id=\"entry-dgp-10053\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διέξοδος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1535 na letra δ · nº geral 10053</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 caminho de saída; passagem de evacuação 2 passagem; fronteira 3 via de fuga; meio de escape 4 percurso; trajeto; órbita (de astro) 5 movimentos (das tropas); expedição 6 exposição detalhada 7 detalhe: κατὰ διέξοδον her. em detalhe.</p></section></article>\n<article id=\"entry-dgp-10054\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεξυφαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1536 na letra δ · nº geral 10054</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(3ª pl. subj. aor. διεξυφήνωσι) tecer por completo; acabar de tecer.</p></section></article>\n<article id=\"entry-dgp-10055\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεορτάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1537 na letra δ · nº geral 10055</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">festejar; celebrar.</p></section></article>\n<article id=\"entry-dgp-10056\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεπέφραδε</h1><div class=\"entry-meta\"><span>DGP · ordem 1538 na letra δ · nº geral 10056</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. aor. de διαφράζω.</p></section></article>\n<article id=\"entry-dgp-10057\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεπλήσθη</h1><div class=\"entry-meta\"><span>DGP · ordem 1539 na letra δ · nº geral 10057</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. διαπίμπλημι.</p></section></article>\n<article id=\"entry-dgp-10058\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διέπραθον</h1><div class=\"entry-meta\"><span>DGP · ordem 1540 na letra δ · nº geral 10058</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. διαπέρθω.</p></section></article>\n<article id=\"entry-dgp-10059\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διέπτατο</h1><div class=\"entry-meta\"><span>DGP · ordem 1541 na letra δ · nº geral 10059</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. aor. de διαπέτομαι.</p></section></article>\n<article id=\"entry-dgp-10060\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διέπω</h1><div class=\"entry-meta\"><span>DGP · ordem 1542 na letra δ · nº geral 10060</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. διεῖπον) 1 comandar; guiar; conduzir 2 atravessar ♦ méd. 3 ocupar-se de; entregar-se a, dat.</p></section></article>\n<article id=\"entry-dgp-10061\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διέραμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1543 na letra δ · nº geral 10061</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">filtro. 〈διεράω〉</p></section></article>\n<article id=\"entry-dgp-10062\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεράω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1544 na letra δ · nº geral 10062</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">filtrar.</p></section></article>\n<article id=\"entry-dgp-10063\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεργάζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1545 na letra δ · nº geral 10063</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 trabalhar com cuidado; realizar 2 pôr fim em; completar 3 destruir; fazer perecer. 〈διά, ἐργάζομαι〉</p></section></article>\n<article id=\"entry-dgp-10064\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διερείδω</h1><div class=\"entry-meta\"><span>DGP · ordem 1546 na letra δ · nº geral 10064</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 apoiar; escorar ♦ méd. 2 apoiar-se em ou sobre, dat. 3 resistir a; lutar por, περί e gen., contra algo, πρός e ac. 〈διά, ἐρείδω〉</p></section></article>\n<article id=\"entry-dgp-10065\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διερευνάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1547 na letra δ · nº geral 10065</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">at. e méd. procurar com cuidado; examinar a fundo. 〈διά, ἐρευνάω〉</p></section></article>\n<article id=\"entry-dgp-10066\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διερευνητής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1548 na letra δ · nº geral 10066</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">explorador; batedor; espião. 〈διε­ρευνάω〉</p></section></article>\n<article id=\"entry-dgp-10067\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διερίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1549 na letra δ · nº geral 10067</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 opor-se a algo, περί e ac. 2 rivalizar com alguém, dat. ♦ méd. 3 contestar alguém, dat. 〈διά, ἐρίζω〉</p></section></article>\n<article id=\"entry-dgp-10068\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διερμηνευτής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1550 na letra δ · nº geral 10068</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. intérprete.</p></section></article>\n<article id=\"entry-dgp-10069\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διερμηνεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1551 na letra δ · nº geral 10069</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. interpretar; explicar.</p></section></article>\n<article id=\"entry-dgp-10070\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διερός1, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1552 na letra δ · nº geral 10070</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que assusta; que faz fugir 2 rápido; ágil; vivaz. 〈δίεσθαι〉</p></section></article>\n<article id=\"entry-dgp-10071\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διερός2, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1553 na letra δ · nº geral 10071</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 úmido; molhado; aquoso 2 que flui; límpido.</p></section></article>\n<article id=\"entry-dgp-10072\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διέρπω</h1><div class=\"entry-meta\"><span>DGP · ordem 1554 na letra δ · nº geral 10072</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διέρψω) 1 recorrer; andar por; arrastar-se através de; avançar por, ac. ou διά e gen.: πῦρ διέρπειν sóf. andar pelo fogo 2 passar 3 (doença) difundir-se. 〈διά, ἕρπω〉</p></section></article>\n<article id=\"entry-dgp-10073\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διερρήθην</h1><div class=\"entry-meta\"><span>DGP · ordem 1555 na letra δ · nº geral 10073</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. pas. de διείρω2.</p></section></article>\n<article id=\"entry-dgp-10074\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διέρρηξα</h1><div class=\"entry-meta\"><span>DGP · ordem 1556 na letra δ · nº geral 10074</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. ind. at. de διαρρήγνυμι.</p></section></article>\n<article id=\"entry-dgp-10075\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διερρύηκα, διερρύην</h1><div class=\"entry-meta\"><span>DGP · ordem 1557 na letra δ · nº geral 10075</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perf. e aor. de διαρρέω.</p></section></article>\n<article id=\"entry-dgp-10076\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διέρρωγα</h1><div class=\"entry-meta\"><span>DGP · ordem 1558 na letra δ · nº geral 10076</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perf. de sent. pas. de διαρρήγνυμι.</p></section></article>\n<article id=\"entry-dgp-10077\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διερύκω</h1><div class=\"entry-meta\"><span>DGP · ordem 1559 na letra δ · nº geral 10077</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 separar 2 pôr fim a uma rixa.</p></section></article>\n<article id=\"entry-dgp-10078\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διέρχομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1560 na letra δ · nº geral 10078</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. δίειμι, aor.2 διῆλθον) 1 ir através; atravessar, ac., gen. ou διά e gen. 2 penetrar profundamente 3 (rumor) espalhar-se 4 percorrer de um extremo a outro; concluir 5 expor até o fim; narrar 6 (tempo) passar; transcorrer. 〈διά, ἔρχομαι〉</p></section></article>\n<article id=\"entry-dgp-10079\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διερῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1561 na letra δ · nº geral 10079</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de διείρω2.</p></section></article>\n<article id=\"entry-dgp-10080\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διερωτάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1562 na letra δ · nº geral 10080</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">interrogar de modo minucioso ou insistente alguém, ac., sobre algo, ac. 〈διά, ἐρωτάω〉</p></section></article>\n<article id=\"entry-dgp-10081\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διέσει</h1><div class=\"entry-meta\"><span>DGP · ordem 1563 na letra δ · nº geral 10081</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. fut. de δίειμι1.</p></section></article>\n<article id=\"entry-dgp-10082\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίεσθαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1564 na letra δ · nº geral 10082</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. de δίεμαι ou de δίομαι.</p></section></article>\n<article id=\"entry-dgp-10083\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεσθίω</h1><div class=\"entry-meta\"><span>DGP · ordem 1565 na letra δ · nº geral 10083</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διέδομαι) devorar; consumir. 〈διά, ἐσθίω〉</p></section></article>\n<article id=\"entry-dgp-10084\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίεσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1566 na letra δ · nº geral 10084</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 facilidade para passar; passagem; escoamento 2 separação; intervalo 3 intervalo musical; sustenido. 〈διΐημι〉</p></section></article>\n<article id=\"entry-dgp-10085\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεσκεμμένως</h1><div class=\"entry-meta\"><span>DGP · ordem 1567 na letra δ · nº geral 10085</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com circunspecção. 〈διασκέπτομαι〉</p></section></article>\n<article id=\"entry-dgp-10086\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διέσσυτο</h1><div class=\"entry-meta\"><span>DGP · ordem 1568 na letra δ · nº geral 10086</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. διασεύομαι.</p></section></article>\n<article id=\"entry-dgp-10087\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεσφαλμένως</h1><div class=\"entry-meta\"><span>DGP · ordem 1569 na letra δ · nº geral 10087</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de modo culposo; de modo errado. 〈διασφάλλω〉</p></section></article>\n<article id=\"entry-dgp-10088\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διετής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1570 na letra δ · nº geral 10088</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que dura dois anos; ἐπὶ διετὲς ἡβᾶν ésqn. ter saído da adolescência há dois anos, i.e., ter 18 anos 2 que tem dois anos de idade. 〈δίς, ἔτος〉</p></section></article>\n<article id=\"entry-dgp-10089\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διετήσιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1571 na letra δ · nº geral 10089</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que dura o ano todo. 〈διά, ἔτος〉</p></section></article>\n<article id=\"entry-dgp-10090\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διετία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1572 na letra δ · nº geral 10090</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. período de dois anos. 〈διετής〉</p></section></article>\n<article id=\"entry-dgp-10091\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διέτμαγεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1573 na letra δ · nº geral 10091</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. διατμήγω.</p></section></article>\n<article id=\"entry-dgp-10092\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διευθύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1574 na letra δ · nº geral 10092</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 endireitar; corrigir 2 percorrer em linha reta. 〈διά, εὐθύνω〉</p></section></article>\n<article id=\"entry-dgp-10093\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διευκρινέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1575 na letra δ · nº geral 10093</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 separar com cuidado; dispor de modo adequado 2 examinar com cuidado ♦ méd. 3 distinguir claramente; decidir após exame cuidadoso; resolver. 〈διά, εὐκρινέω〉</p></section></article>\n<article id=\"entry-dgp-10094\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διευνάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1576 na letra δ · nº geral 10094</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(inf. aor. διευνᾶσαι) pôr para dormir, ac.</p></section></article>\n<article id=\"entry-dgp-10095\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διευσχημονέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1577 na letra δ · nº geral 10095</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">guardar compostura; manter o decoro; viver dignamente.</p></section></article>\n<article id=\"entry-dgp-10096\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διευτελίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1578 na letra δ · nº geral 10096</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">depreciar; avaliar a baixo preço.</p></section></article>\n<article id=\"entry-dgp-10097\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διευτυχέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1579 na letra δ · nº geral 10097</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ter boa sorte continuamente; ser sempre feliz; ter êxitos contínuos.</p></section></article>\n<article id=\"entry-dgp-10098\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεφθαρέατο</h1><div class=\"entry-meta\"><span>DGP · ordem 1580 na letra δ · nº geral 10098</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. m.-q.-perf. pas. jôn. de διαφθείρω.</p></section></article>\n<article id=\"entry-dgp-10099\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεφθάρην, διέφθαρκα, διέφθορα</h1><div class=\"entry-meta\"><span>DGP · ordem 1581 na letra δ · nº geral 10099</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. διαφθείρω.</p></section></article>\n<article id=\"entry-dgp-10100\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διέχεα, διέχευα</h1><div class=\"entry-meta\"><span>DGP · ordem 1582 na letra δ · nº geral 10100</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. διαχέω.</p></section></article>\n";
